#include "../../mods/tank_auto_repair_module.hpp"
#include <MinHook.h>
namespace tr=goh::tank_auto_repair;
extern "C" __declspec(dllexport) bool prepare(tr::Address image,const char* sha) {
    return tr::prepare_hooks(image,sha,MH_CreateHook,MH_RemoveHook);
}
extern "C" __declspec(dllexport) void post(tr::Address actor) {tr::on_actor_post_quant(actor);}
extern "C" __declspec(dllexport) int stop() {tr::deactivate();return tr::inflight_count();}
extern "C" __declspec(dllexport) void removed(){tr::after_hooks_removed();}
